// Event Delegation on a list
const list = document.querySelector('#job-listings');
list.addEventListener('click', (e) => {
  const card = e.target.closest('.job-card');
  if (card && list.contains(card)) {
    handleJobClick(card.dataset.jobId);
  }
});
